/* prog59_rule110.c – reproduces the observable behaviour of prog59_rule110 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 60
#define MAX_STEPS 200

/* Rule 110 lookup table: index = left*4 + center*2 + right */
static const int RULE110[8] = {
    0, /* 000 */
    1, /* 001 */
    1, /* 010 */
    1, /* 011 */
    0, /* 100 */
    1, /* 101 */
    1, /* 110 */
    0  /* 111 */
};

/* Print the row stored in buf (length len) as '0'/'1' characters */
static void print_row(const char *buf, size_t len)
{
    for (size_t i = 0; i < len; ++i)
        putchar(buf[i]);
    putchar('\n');
}

/* Compute the next row according to Rule 110.
   src and dst may point to the same buffer (they are never overlapped in this program). */
static void next_row(const char *src, char *dst, size_t len)
{
    for (size_t i = 0; i < len; ++i) {
        int left   = (i == 0)     ? 0 : (src[i - 1] - '0');
        int center = src[i] - '0';
        int right  = (i + 1 == len) ? 0 : (src[i + 1] - '0');

        int pattern = (left << 2) | (center << 1) | right;
        dst[i] = (char)('0' + RULE110[pattern]);
    }
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("INVALID_INPUT");
        return 1;
    }

    const char *init = argv[1];
    size_t len = strlen(init);

    /* length must be between 1 and MAX_LEN and contain only '0'/'1' */
    if (len == 0 || len > MAX_LEN) {
        puts("INVALID_INPUT");
        return 1;
    }
    for (size_t i = 0; i < len; ++i) {
        if (init[i] != '0' && init[i] != '1') {
            puts("INVALID_INPUT");
            return 1;
        }
    }

    char *endptr;
    long steps = strtol(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0') {
        puts("INVALID_INPUT");
        return 1;
    }
    if (steps < 0) {
        puts("INVALID_INPUT");
        return 1;
    }
    if (steps > MAX_STEPS)
        steps = MAX_STEPS;

    /* buffers for the current and next rows */
    char cur[MAX_LEN];
    char nxt[MAX_LEN];
    memcpy(cur, init, len);

    /* print the initial row */
    print_row(cur, len);

    for (long i = 1; i < steps; ++i) {
        next_row(cur, nxt, len);
        print_row(nxt, len);
        memcpy(cur, nxt, len);
    }

    return 0;
}
